function sh(n){var j={};try{j=$(n).first().json||{};}catch(e){return [];}return j.values||[];}
function s(v){return String(v==null?'':v).trim();}
var out={};

var rows=sh('Read ONB');
var hdr=(rows[0]||[]).map(s);
out.onb_header_full=hdr;
out.onb_header_AQ_AV=hdr.slice(42,48);
var lc=hdr.map(function(x){return x.toLowerCase();});
function col(n,f){var i=lc.indexOf(n);return i>=0?i:f;}
var C={status:col('status',4),firm:col('firm',5),contact:col('contact',6),email:col('email',8),sent:col('sent_date',27),thread:col('thread_id',28),rr:col('reply_received',29),oc:col('outcome',36)};
out.onb_cols=C;
var onb=[];var stageCount={};
for(var i=1;i<rows.length;i++){
  var r=rows[i]||[];
  var stage=s(r[42]);
  var rrv=s(r[C.rr]);
  if(stage){stageCount[stage]=(stageCount[stage]||0)+1;}
  if(!stage && !rrv && (i+1)!==18) continue;
  onb.push({row:i+1,firm:s(r[C.firm]),contact:s(r[C.contact]),email:s(r[C.email]),status:s(r[C.status]),sent_date:s(r[C.sent]),thread_id:s(r[C.thread]),reply:rrv.slice(0,700),outcome:s(r[C.oc]).slice(0,200),stage:stage,meeting_asked_date:s(r[43]),manager_notified_date:s(r[44]),next_action:s(r[45]).slice(0,200),next_action_due:s(r[46]),engine_log:s(r[47]).slice(0,400)});
}
out.onb_data_rows=rows.length-1;
out.onb_stageCount=stageCount;
out.onb=onb;

var l=sh('Read LI');
var lh=(l[0]||[]).map(s);
out.li_header_full=lh;
out.li_header_V_AA=lh.slice(21,27);
var li=[];var liStage={};
for(var k=1;k<l.length;k++){
  var q=l[k]||[];
  var any=false;for(var z=0;z<q.length;z++){if(s(q[z])){any=true;break;}}
  if(!any) continue;
  var st=s(q[21]);
  if(st){liStage[st]=(liStage[st]||0)+1;}
  if(!st) continue;
  li.push({row:k+1,vals:q.map(s).slice(0,27)});
}
out.li_data_rows=l.length-1;
out.li_stageCount=liStage;
out.li_with_stage=li;

return [{json:out}];
